                    Type pt = emit_resolve_type(
                        ctx, *fn_binding->type.as.fn.arg_full_types[i]);
                    bool pbp = (pt.kind == TY_ADT && pt.as.adt_.def)
                                   ? adt_byval_pass_by_ptr(pt.as.adt_.def)
                                   : adt_app_byval_pass_by_ptr(pt);
