                        uint8_t param_idx = (i < n_fnparams) ? (uint8_t)i
                            : (uint8_t)(n_fnparams > 0 ? n_fnparams - 1 : 0);
                        TypeKind pk = fn_binding->type.as.fn.arg_kinds[param_idx];
